"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant0 from "./components/ai-thinking-loader/variants/01-orbit";
import Variant1 from "./components/ai-thinking-loader/variants/02-scan";
import Variant2 from "./components/ai-thinking-loader/variants/03-wave";
import Variant3 from "./components/ai-thinking-loader/variants/04-assemble";
import Variant4 from "./components/ai-thinking-loader/variants/05-diamond";
import Variant5 from "./components/ai-thinking-loader/variants/06-nodes";
const variants = {"orbit": Variant0,"scan": Variant1,"wave": Variant2,"assemble": Variant3,"diamond": Variant4,"nodes": Variant5};
export interface ArtemisAiThinkingLoaderProps { className?: string; variant?: "orbit" | "scan" | "wave" | "assemble" | "diamond" | "nodes"; }
export function ArtemisAiThinkingLoader({ className, variant = "orbit" }: ArtemisAiThinkingLoaderProps) { const View = variants[variant]; return <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}><div className="art:flex art:w-full art:justify-center"><View/></div></ArtemisScope>; }
